export const HOST_VERSION=1,MAX_ARTIFACT_BYTES=52428800,hostActions=new Set(["state","reserve","submit","release","sign-in","library","recordings","lifecycle","card-clips","resume-intent","remote-render"]),sessionToken=e=>typeof e=="string"&&/^[a-zA-Z0-9_-]{16,128}$/.test(e);export function hostEnvelope(e,t){return!!e&&typeof e=="object"&&!Array.isArray(e)&&e.namespace==="vireel-host"&&e.version===1&&e.sessionId===t&&sessionToken(e.sessionId)}export function scalarConfig(e){if(!e||typeof e!="object"||Array.isArray(e)||Object.keys(e).length>30)throw new Error("Invalid recording configuration.");const t={};for(const[o,r]of Object.entries(e)){if(!/^[a-zA-Z][\w]{0,39}$/.test(o)||["__proto__","prototype","constructor"].includes(o)||!(typeof r=="string"&&r.length<=200||typeof r=="number"&&Number.isFinite(r)||typeof r=="boolean"))throw new Error("Recording configuration must contain bounded scalar values.");t[o]=r}return t}export function checkedArtifact(e){if(!(e instanceof Blob)||e.size<12||e.size>52428800||!/^video\/(mp4|webm)(;|$)/.test(e.type))throw new Error("Recording must be a real MP4 or WebM file smaller than 50 MB.");return e}
